          "evidence": "The horizontal axis at the bottom is labeled 'Advertising Spend ($ thousands)'.",
          "status": "supported"
        },
        "3": {
          "evidence": "The vertical axis on the left is labeled 'Sales ($ thousands)'.",
          "status": "supported"
